ruleBookInfo.intro:
@js:
var s = String(result || '').replace(/\r/g, '');
var out = '';
var i = s.indexOf('小说简介');
if (i < 0) i = s.indexOf('内容简介');
if (i > -1) {
  s = s.substring(i);
  var p = s.indexOf('</p>');
  if (p > -1) s = s.substring(p + 4);
  var ends = ['<div align="center"', '<div class="pageMainArea"', '<script'];
  for (var n = 0; n < ends.length; n++) {
    var j = s.indexOf(ends[n]);
    if (j > -1) s = s.substring(0, j);
  }
  out = s.replace(/<br\s*\/?>/ig, '\n').replace(/<[^>]+>/g, '').replace(/&nbsp;/g, ' ').replace(/&raquo;/g, '').replace(/^[\s\n]+/, '').replace(/[\s\n]+$/, '');
}
out;

ruleContent.content:
@js:
var s = String(result || '');
var out;
if (s.substr(0, 2) == 'PK' && s.charCodeAt(2) == 3) {
  out = '【压缩包】本站在该书上架较早，只提供 ZIP 压缩包（无在线阅读页），阅读器无法解压。\n请复制本章链接用浏览器下载后，用「本地导入」阅读：\n' + String(baseUrl);
} else {
  if (s.indexOf('\uFFFD') > -1) {
    try { s = String(java.ajax(String(baseUrl) + ',{"charset":"gb18030"}')); } catch (e) { }
  }
  if (s.indexOf('\uFFFD') > -1) {
    try { s = String(java.ajax(String(baseUrl) + ',{"charset":"utf-8"}')); } catch (e) { }
  }
  var c = s.indexOf('class="content-box"');
  if (c > -1) {
    s = s.substring(s.indexOf('>', c) + 1);
  }
  var b = s.indexOf('下载本书');
  if (b > -1) s = s.substring(0, b);
  s = s.replace(/推荐一个小说下载必备网址[^<\r\n]*/g, '');
  s = s.replace(/每天更新，喜欢的去看看。[^<\r\n]*/g, '');
  out = s.replace(/\uFEFF/g, '').replace(/\u3000\u3000/g, '\n');
}
out;
